## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/brainMetastasesLogic.ts`

```typescript
/**
 * Brain Metastases Clinical Logic Engine
 *
 * Based on:
 * - CNS 2025 Systematic Review and Evidence-Based Guidelines for Emerging Therapies
 *   for Adults with Metastatic Brain Tumors (Neurosurgery, 2025)
 * - ASTRO/AANS/SNO Brain Metastases Guidelines
 * - NCCN CNS Tumors Guidelines v2.2025
 * - ASCO Brain Metastases Guidelines 2022
 *
 * PMIDs: 35417433, 34936423, 36523687
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type PrimaryHistology =
  | "nsclc_egfr"
  | "nsclc_alk"
  | "nsclc_other"
  | "melanoma_braf"
  | "melanoma_other"
  | "breast_her2"
  | "breast_hr_pos"
  | "breast_tnbc"
  | "sclc"
  | "renal_cell"
  | "colorectal"
  | "other";

export type MetastasisCount =
  | "single" // 1
  | "limited" // 2–4
  | "multiple" // 5–10
  | "disseminated"; // >10

export type KPSScore =
  | "high" // ≥70
  | "intermediate" // 50–69
  | "low"; // <50

export type PrimaryRecommendation =
  | "surgery_plus_srs"
  | "srs_alone"
  | "wbrt"
  | "systemic_therapy_first"
  | "srs_plus_systemic"
  | "litt_option"
  | "best_supportive_care"
  | "multidisciplinary_evaluation";

export interface BrainMetastasesInput {
  // Tumor characteristics
  primaryHistology: PrimaryHistology;
  metastasisCount: MetastasisCount;
  largestLesionCm: number;
  leptomeningealDisease: boolean;
  symptomatic: boolean;
  massEffect: boolean;

  // Molecular markers
  egfrMutation?: boolean;
  alkMutation?: boolean;
  brafV600E?: boolean;
  her2Positive?: boolean;
  pdl1Expression?: "low" | "intermediate" | "high" | "unknown";

  // Patient factors
  kpsScore: KPSScore;
  ageYears: number;
  controlledExtracranialDisease: boolean;
  extracranialMetastases: boolean;

  // Treatment history
  priorWBRT: boolean;
  priorSRS: boolean;
  priorSurgery: boolean;
  priorSystemicTherapy: boolean;
  currentSystemicTherapy: boolean;

  // Functional status
  neurologicDeficit: boolean;
  seizureHistory: boolean;
  performanceStatusDecline: boolean;
}

export interface BrainMetastasesRecommendation {
  primaryRecommendation: PrimaryRecommendation;
  recommendationTitle: string;
  rationale: string;
  evidenceLevel: "I" | "II" | "III";
  guidelineSource: string;

  // Treatment details
  localTherapyOptions: string[];
  systemicTherapyOptions: string[];
  surgicalConsiderations: string[];

  // Monitoring
  monitoringPlan: string[];

  // Warnings and flags
  urgentFlags: string[];
  warnings: string[];

  // Next steps
  nextSteps: string[];

  // References
  references: Array<{ citation: string; pmid?: string }>;
}

// ─── Core Logic ──────────────────────────────────────────────────────────────

export function assessBrainMetastases(
  input: BrainMetastasesInput
): BrainMetastasesRecommendation {
  const urgentFlags: string[] = [];
  const warnings: string[] = [];
  const localTherapyOptions: string[] = [];
  const systemicTherapyOptions: string[] = [];
  const surgicalConsiderations: string[] = [];
  const monitoringPlan: string[] = [];

  // ── Urgent flags ──────────────────────────────────────────────────────────
  if (input.leptomeningealDisease) {
    urgentFlags.push(
      "Leptomeningeal disease (LMD): Systemic and intrathecal therapy considerations. Prognosis significantly worse. Urgent multidisciplinary oncology review."
    );
  }
  if (input.massEffect && input.symptomatic) {
    urgentFlags.push(
      "Symptomatic mass effect: Consider urgent corticosteroids (dexamethasone 4–16 mg/day) and expedited neurosurgical evaluation."
    );
  }
  if (input.neurologicDeficit && input.massEffect) {
    urgentFlags.push(
      "Progressive neurologic deficit with mass effect: Urgent surgical evaluation for decompression."
    );
  }

  // ── Poor performance status — best supportive care ────────────────────────
  if (input.kpsScore === "low") {
    return {
      primaryRecommendation: "best_supportive_care",
      recommendationTitle: "Best Supportive Care / Palliative Approach",
      rationale:
        "KPS <50 is associated with poor prognosis regardless of treatment. Aggressive local or systemic therapy is unlikely to provide meaningful benefit. Palliative care, symptom management, and goals-of-care discussion are recommended.",
      evidenceLevel: "III",
      guidelineSource:
        "CNS 2025 Brain Metastases Guidelines; ASCO 2022 Brain Metastases Guidelines",
      localTherapyOptions: [
        "Corticosteroids for symptom management (dexamethasone 4–8 mg/day)",
        "WBRT may be considered for symptom palliation in selected patients",
      ],
      systemicTherapyOptions: [
        "Continue targeted therapy if tolerated and previously effective",
        "Avoid aggressive cytotoxic chemotherapy",
      ],
      surgicalConsiderations: [
        "Surgery generally not recommended with KPS <50 unless for emergency decompression",
      ],
      monitoringPlan: [
        "Palliative care consultation",
        "Goals-of-care discussion",
        "Symptom-directed follow-up",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "Prognosis: Median OS with KPS <50 is typically <2 months regardless of treatment.",
      ],
      nextSteps: [
        "Palliative care consultation",
        "Goals-of-care discussion with patient and family",
        "Corticosteroids for symptom management",
        "Hospice evaluation if appropriate",
      ],
      references: getBrainMetsReferences(),
    };
  }

  // ── NSCLC with EGFR mutation ──────────────────────────────────────────────
  if (input.primaryHistology === "nsclc_egfr" && input.egfrMutation) {
    systemicTherapyOptions.push(
      "Osimertinib (3rd-gen EGFR TKI): CNS penetration >60%, intracranial ORR ~70%. FLAURA2 trial: significant intracranial PFS benefit."
    );
    systemicTherapyOptions.push(
      "EGFR TKIs + WBRT or SRS: Addition of EGFR TKIs to WBRT or SRS suggested to improve OS, PFS, and intracranial PFS (CNS 2025, Level III)."
    );
    if (input.metastasisCount !== "single" && input.metastasisCount !== "limited") {
      systemicTherapyOptions.push(
        "Icotinib + WBRT: Recommended for NSCLC with EGFR mutation and ≥3 untreated brain metastases to improve intracranial PFS (CNS 2025, Level I)."
      );
    }
    if (input.metastasisCount === "single" || input.metastasisCount === "limited") {
      localTherapyOptions.push(
        "SRS + osimertinib: Preferred for limited brain metastases with EGFR mutation."
      );
    }
    return buildSystemicPlusLocalRecommendation(
      input,
      "NSCLC EGFR-Mutant: Targeted Therapy + Local Therapy",
      "NSCLC with EGFR mutation: Osimertinib has excellent CNS penetration and is the preferred systemic agent. For ≥3 untreated metastases, icotinib + WBRT improves intracranial PFS (Level I). EGFR TKIs + WBRT or SRS improves OS and PFS (Level III).",
      "I",
      urgentFlags,
      warnings,
      localTherapyOptions,
      systemicTherapyOptions,
      surgicalConsiderations,
      monitoringPlan
    );
  }

  // ── NSCLC with ALK mutation ───────────────────────────────────────────────
  if (input.primaryHistology === "nsclc_alk" && input.alkMutation) {
    systemicTherapyOptions.push(
      "Alectinib: Recommended to delay intracranial tumor progression in ALK-mutant NSCLC with untreated brain metastases (CNS 2025, Level I)."
    );
    systemicTherapyOptions.push(
      "Lorlatinib: Recommended to prolong intracranial tumor control and improve overall PFS (CNS 2025, Level II)."
    );
    systemicTherapyOptions.push(
      "Brigatinib: Alternative ALK inhibitor with CNS activity."
    );
    return buildSystemicPlusLocalRecommendation(
      input,
      "NSCLC ALK-Mutant: ALK Inhibitor Therapy",
      "ALK-mutant NSCLC with brain metastases: Alectinib is recommended to delay intracranial progression (Level I). Lorlatinib prolongs intracranial tumor control and improves overall PFS (Level II). These agents have excellent CNS penetration and may defer or eliminate need for local therapy.",
      "I",
      urgentFlags,
      warnings,
      localTherapyOptions,
      systemicTherapyOptions,
      surgicalConsiderations,
      monitoringPlan
    );
  }

  // ── Melanoma with BRAF V600E mutation ─────────────────────────────────────
  if (input.primaryHistology === "melanoma_braf" && input.brafV600E) {
    systemicTherapyOptions.push(
      "Dabrafenib + trametinib: Recommended for BRAF V600E-mutant melanoma brain metastases for local tumor control (CNS 2025, Level I). Intracranial ORR ~60%."
    );
    systemicTherapyOptions.push(
      "Ipilimumab + nivolumab: Recommended for active, untreated, asymptomatic parenchymal melanoma brain metastases to increase median OS (CNS 2025, Level I)."
    );
    return buildSystemicPlusLocalRecommendation(
      input,
      "Melanoma BRAF V600E: Targeted Therapy + Immunotherapy",
      "BRAF V600E-mutant melanoma brain metastases: Dabrafenib + trametinib recommended for local tumor control (Level I). Ipilimumab + nivolumab recommended for active asymptomatic parenchymal metastases to improve OS (Level I). Combination of targeted therapy + immunotherapy may be considered in sequence.",
      "I",
      urgentFlags,
      warnings,
      localTherapyOptions,
      systemicTherapyOptions,
      surgicalConsiderations,
      monitoringPlan
    );
  }

  // ── Melanoma (non-BRAF or unknown) ────────────────────────────────────────
  if (
    input.primaryHistology === "melanoma_other" ||
    input.primaryHistology === "melanoma_braf"
  ) {
    systemicTherapyOptions.push(
      "Ipilimumab + nivolumab: Recommended for active, untreated, asymptomatic parenchymal melanoma brain metastases (CNS 2025, Level I)."
    );
    systemicTherapyOptions.push(
      "Pembrolizumab: Alternative checkpoint inhibitor with intracranial activity."
    );
  }

  // ── Single/limited metastases — surgery or SRS ────────────────────────────
  if (
    input.metastasisCount === "single" ||
    input.metastasisCount === "limited"
  ) {
    if (
      input.largestLesionCm >= 3 ||
      (input.symptomatic && input.massEffect)
    ) {
      surgicalConsiderations.push(
        "Large lesion (≥3 cm) or symptomatic mass effect: Surgical resection preferred for immediate decompression and tissue diagnosis."
      );
      surgicalConsiderations.push(
        "Post-resection SRS to cavity: Reduces local recurrence vs observation (Level I evidence from multiple RCTs)."
      );
      localTherapyOptions.push(
        "Surgical resection + post-operative cavity SRS (preferred for large/symptomatic lesions)"
      );
      localTherapyOptions.push(
        "SRS alone: Acceptable for lesions <3 cm without significant mass effect"
      );
      return {
        primaryRecommendation: "surgery_plus_srs",
        recommendationTitle:
          "Surgical Resection + Post-Operative Cavity SRS",
        rationale:
          "Single or limited brain metastases with large lesion (≥3 cm) or symptomatic mass effect: Surgical resection provides immediate decompression, tissue diagnosis, and reduces tumor burden. Post-operative cavity SRS reduces local recurrence.",
        evidenceLevel: "II",
        guidelineSource:
          "CNS 2025 Brain Metastases Guidelines; ASCO 2022 Brain Metastases Guidelines (PMID 34936423)",
        localTherapyOptions,
        systemicTherapyOptions,
        surgicalConsiderations,
        monitoringPlan: [
          "MRI brain at 6–8 weeks post-surgery/SRS",
          "MRI brain every 2–3 months × 1 year, then every 3–4 months",
          "Systemic staging CT every 3 months",
        ],
        urgentFlags,
        warnings: [
          ...warnings,
          "Post-resection SRS to cavity: Reduces local recurrence. WBRT should be avoided if SRS is feasible (neurocognitive toxicity).",
        ],
        nextSteps: [
          "Neurosurgery consultation for resection planning",
          "Radiation oncology consultation for post-operative cavity SRS",
          "Medical oncology for systemic therapy coordination",
          "Tissue for molecular profiling if not previously obtained",
          "MRI brain with gadolinium (thin-cut) for surgical planning",
        ],
        references: getBrainMetsReferences(),
      };
    }

    // Small single/limited — SRS alone
    localTherapyOptions.push(
      "SRS (Gamma Knife, CyberKnife, or LINAC-based): Preferred for limited brain metastases <3 cm without significant mass effect."
    );
    localTherapyOptions.push(
      "WBRT: Generally avoided in favor of SRS due to neurocognitive toxicity (QUARTZ trial, NCCTG N0574)."
    );
    return {
      primaryRecommendation: "srs_alone",
      recommendationTitle: "Stereotactic Radiosurgery (SRS) — Recommended",
      rationale:
        "SRS is the preferred local therapy for limited brain metastases (<3 cm, no significant mass effect). Provides excellent local control (>80% at 1 year) with preservation of neurocognitive function. WBRT should be deferred due to neurocognitive toxicity.",
      evidenceLevel: "I",
      guidelineSource:
        "CNS 2025 Brain Metastases Guidelines; ASCO 2022 (PMID 34936423)",
      localTherapyOptions,
      systemicTherapyOptions,
      surgicalConsiderations,
      monitoringPlan: [
        "MRI brain at 6–8 weeks post-SRS",
        "MRI brain every 2–3 months × 1 year",
        "Systemic staging CT every 3 months",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "Radiographic progression at 3–6 months may represent radiation necrosis vs true progression — MRI perfusion or PET may help differentiate.",
        "LITT (laser interstitial thermal therapy): Considered equivalent to craniotomy for recurrent brain metastases after SRS (CNS 2025, Level III).",
      ],
      nextSteps: [
        "Radiation oncology consultation for SRS planning",
        "Medical oncology for systemic therapy coordination",
        "MRI brain with gadolinium (thin-cut) for SRS planning",
        "Molecular profiling of primary tumor if not done",
        "Neurocognitive baseline assessment",
      ],
      references: getBrainMetsReferences(),
    };
  }

  // ── Multiple/disseminated metastases ──────────────────────────────────────
  if (
    input.metastasisCount === "multiple" ||
    input.metastasisCount === "disseminated"
  ) {
    // Actionable molecular target — systemic therapy first
    if (
      input.egfrMutation ||
      input.alkMutation ||
      input.brafV600E ||
      input.her2Positive
    ) {
      return buildSystemicPlusLocalRecommendation(
        input,
        "Multiple Brain Metastases with Actionable Target: Systemic Therapy First",
        "Multiple brain metastases with actionable molecular target: CNS-penetrant targeted therapy is preferred first-line approach. Local therapy (SRS or WBRT) reserved for symptomatic lesions or progression on systemic therapy.",
        "II",
        urgentFlags,
        warnings,
        localTherapyOptions,
        systemicTherapyOptions,
        surgicalConsiderations,
        monitoringPlan
      );
    }

    // No actionable target — WBRT or SRS to multiple lesions
    localTherapyOptions.push(
      "SRS to multiple lesions (up to 10–15): Preferred over WBRT if feasible to preserve neurocognitive function."
    );
    localTherapyOptions.push(
      "WBRT: Consider for disseminated disease (>10 lesions) or leptomeningeal disease."
    );
    localTherapyOptions.push(
      "Hippocampal-avoidance WBRT + memantine: If WBRT required, reduces neurocognitive toxicity."
    );
    warnings.push(
      "WBRT neurocognitive toxicity: Avoid if SRS to multiple lesions is feasible. Hippocampal-avoidance WBRT + memantine reduces cognitive decline."
    );

    return {
      primaryRecommendation: "wbrt",
      recommendationTitle:
        "Whole Brain Radiation Therapy (WBRT) or Multi-Lesion SRS",
      rationale:
        "Multiple/disseminated brain metastases without actionable molecular target: WBRT or SRS to multiple lesions. Hippocampal-avoidance WBRT + memantine preferred if WBRT is required to reduce neurocognitive toxicity.",
      evidenceLevel: "II",
      guidelineSource:
        "CNS 2025 Brain Metastases Guidelines; ASCO 2022 (PMID 34936423)",
      localTherapyOptions,
      systemicTherapyOptions,
      surgicalConsiderations: [
        "Surgery for single dominant symptomatic lesion causing mass effect",
      ],
      monitoringPlan: [
        "MRI brain at 4–6 weeks post-WBRT",
        "MRI brain every 2–3 months",
        "Neurocognitive assessment at 3 and 6 months",
      ],
      urgentFlags,
      warnings,
      nextSteps: [
        "Radiation oncology consultation",
        "Medical oncology for systemic therapy coordination",
        "Molecular profiling if not done",
        "Neurocognitive baseline assessment",
        "Consider SRS to multiple lesions if ≤10 lesions and KPS ≥70",
      ],
      references: getBrainMetsReferences(),
    };
  }

  // ── Default: multidisciplinary evaluation ────────────────────────────────
  return {
    primaryRecommendation: "multidisciplinary_evaluation",
    recommendationTitle: "Multidisciplinary Tumor Board Evaluation",
    rationale:
      "Complex brain metastases case requiring multidisciplinary tumor board review involving neurosurgery, radiation oncology, and medical oncology.",
    evidenceLevel: "III",
    guidelineSource: "CNS 2025 Brain Metastases Guidelines",
    localTherapyOptions,
    systemicTherapyOptions,
    surgicalConsiderations,
    monitoringPlan: ["MRI brain with gadolinium", "Systemic staging"],
    urgentFlags,
    warnings,
    nextSteps: [
      "Multidisciplinary tumor board presentation",
      "Neurosurgery, radiation oncology, and medical oncology consultation",
      "Molecular profiling of primary tumor",
    ],
    references: getBrainMetsReferences(),
  };
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

function buildSystemicPlusLocalRecommendation(
  input: BrainMetastasesInput,
  title: string,
  rationale: string,
  evidenceLevel: "I" | "II" | "III",
  urgentFlags: string[],
  warnings: string[],
  localTherapyOptions: string[],
  systemicTherapyOptions: string[],
  surgicalConsiderations: string[],
  monitoringPlan: string[]
): BrainMetastasesRecommendation {
  const localOptions = [...localTherapyOptions];
  if (
    input.metastasisCount === "single" ||
    input.metastasisCount === "limited"
  ) {
    localOptions.push(
      "SRS to limited metastases: Consider in addition to systemic therapy for durable local control."
    );
  }
  if (input.symptomatic && input.massEffect) {
    localOptions.push(
      "Urgent local therapy (SRS or surgery) for symptomatic lesions regardless of systemic therapy status."
    );
  }

  return {
    primaryRecommendation: "srs_plus_systemic",
    recommendationTitle: title,
    rationale,
    evidenceLevel,
    guidelineSource:
      "CNS 2025 Brain Metastases Guidelines (Huntoon K et al., Neurosurgery 2025; PMID 35417433)",
    localTherapyOptions: localOptions,
    systemicTherapyOptions,
    surgicalConsiderations,
    monitoringPlan: [
      "MRI brain at 6–8 weeks after initiating systemic therapy",
      "MRI brain every 2–3 months",
      "Systemic staging CT every 3 months",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      "Immunotherapy + SRS: Combination may increase radiation necrosis risk — timing and sequencing require multidisciplinary coordination.",
    ],
    nextSteps: [
      "Medical oncology consultation for systemic therapy initiation",
      "Radiation oncology consultation for SRS planning",
      "Molecular profiling confirmation",
      "MRI brain with gadolinium (thin-cut) for treatment planning",
      "Multidisciplinary tumor board review",
    ],
    references: getBrainMetsReferences(),
  };
}

function getBrainMetsReferences() {
  return [
    {
      citation:
        "Huntoon K et al. CNS Systematic Review and Evidence-Based Guidelines for Emerging Therapies for Adults with Metastatic Brain Tumors. Neurosurgery. 2025.",
      pmid: "35417433",
    },
    {
      citation:
        "Vogelbaum MA et al. Treatment for Brain Metastases: ASCO-SNO-ASTRO Guideline. J Clin Oncol. 2022;40(5):492-516.",
      pmid: "34936423",
    },
    {
      citation:
        "Ramos A et al. Brain Metastases: An Overview of Current Management. Neuro Oncol. 2022.",
      pmid: "36523687",
    },
    {
      citation:
        "Brown PD et al. Postoperative Stereotactic Radiosurgery Compared with Whole Brain Radiotherapy for Resected Metastatic Brain Disease (NCCTG N107C/CEC.3). Lancet Oncol. 2017;18(8):1049-1060.",
      pmid: "28687387",
    },
    {
      citation:
        "Soria JC et al. Osimertinib in Untreated EGFR-Mutated Advanced Non-Small-Cell Lung Cancer (FLAURA). N Engl J Med. 2018;378(2):113-125.",
      pmid: "29151359",
    },
    {
      citation:
        "Peters S et al. Alectinib versus Crizotinib in Untreated ALK-Positive Non-Small-Cell Lung Cancer (ALEX). N Engl J Med. 2017;377(9):829-838.",
      pmid: "28586279",
    },
    {
      citation:
        "Long GV et al. Dabrafenib plus Trametinib versus Dabrafenib Monotherapy in Patients with Metastatic BRAF V600E/K-Mutant Melanoma. Lancet Oncol. 2015;16(8):954-963.",
      pmid: "26115796",
    },
  ];
}

export function getRecommendationColor(rec: PrimaryRecommendation): string {
  switch (rec) {
    case "surgery_plus_srs":
      return "blue";
    case "srs_alone":
      return "purple";
    case "srs_plus_systemic":
      return "indigo";
    case "systemic_therapy_first":
      return "green";
    case "wbrt":
      return "orange";
    case "litt_option":
      return "yellow";
    case "best_supportive_care":
      return "gray";
    case "multidisciplinary_evaluation":
      return "teal";
    default:
      return "gray";
  }
}

export function getHistologyLabel(h: PrimaryHistology): string {
  const labels: Record<PrimaryHistology, string> = {
    nsclc_egfr: "NSCLC — EGFR mutation",
    nsclc_alk: "NSCLC — ALK rearrangement",
    nsclc_other: "NSCLC — No actionable mutation",
    melanoma_braf: "Melanoma — BRAF V600E",
    melanoma_other: "Melanoma — BRAF wild-type",
    breast_her2: "Breast — HER2-positive",
    breast_hr_pos: "Breast — HR-positive, HER2-negative",
    breast_tnbc: "Breast — Triple-negative",
    sclc: "Small Cell Lung Cancer (SCLC)",
    renal_cell: "Renal Cell Carcinoma",
    colorectal: "Colorectal Cancer",
    other: "Other / Unknown Primary",
  };
  return labels[h] ?? h;
}
